const RE_PY_ROUTE = /^\s*@\s*([A-Za-z_]\w*)\.(route|get|post|put|patch|delete|options|head|api_route|websocket)\s*\(\s*(?:(?:path|rule)\s*=\s*)?[rRuUbBfF]{0,2}(['"])([^'"]*)\3(.*)$/;
